def get_race(rid):
    return RACES[rid]

def evolution_stage(rid, level):
    r = RACES[rid]
    stage = {'name': r['name'], 'mult': {}, 'grants': []}
    for evo in r['evolution']:
        if level >= evo['level']:
            stage = {'name': evo['stage'], 'mult': evo['mult'], 'grants': evo.get('grant', [])}
    return stage
